import{t as e}from"./jsx-runtime-CondluQF.js";import{t}from"./scissors-iJAAquS5.js";import{o as n,t as r}from"./index-DAXTygfX.js";import{i,n as a,r as o,t as s}from"./ArticleLayout-LOf58JDQ.js";var c=e(),l=r.find(e=>e.path===`/blog/planning-rdv-coiffeur/`);function u(){return(0,c.jsxs)(a,{icon:t,accent:`pink`,category:l.category,title:l.heading,date:l.date,readTime:l.readTime,children:[(0,c.jsx)(i,{children:`Répondre au téléphone les mains dans les cheveux d'une cliente, jongler entre un agenda papier et un planning par praticien, relancer soi-même les rendez-vous du lendemain : la gestion des rendez-vous reste l'un des points de friction les plus fréquents dans les salons de coiffure et instituts. Un logiciel de planning en ligne change concrètement ce quotidien.`}),(0,c.jsx)(s,{children:`Pourquoi la prise de rendez-vous papier montre ses limites`}),(0,c.jsx)(i,{children:`Un salon qui grandit, c'est plusieurs praticiens, plusieurs plannings à coordonner, et des clientes qui souhaitent réserver en dehors des horaires d'ouverture. Le papier ou un simple agenda partagé ne permet ni la réservation autonome par la cliente, ni les rappels automatiques, ni une vue claire du taux de remplissage par coiffeur ou praticien.`}),(0,c.jsx)(s,{children:`Ce qu'apporte un planning en ligne`}),(0,c.jsx)(i,{children:`Le module Planning Coiffeur de WebMétier est pensé pour les salons et instituts qui veulent reprendre la main sur leur agenda :`}),(0,c.jsx)(o,{items:[`Prise de rendez-vous en ligne accessible 24h/24 et 7j/7`,`Planning individuel pour chaque coiffeur ou praticien`,`Programme de fidélité et suivi de la clientèle`,`Rappels automatiques 24h avant le rendez-vous`,`Catalogue de prestations avec tarifs à jour`,`Statistiques de chiffre d'affaires par praticien`]}),(0,c.jsx)(s,{children:`Moins de rendez-vous manqués, plus de temps pour le service`}),(0,c.jsx)(i,{children:`Les rappels automatiques par SMS ou email limitent les oublis, sans que l'équipe ait à y penser. Et parce que chaque praticien dispose de son propre planning, il devient facile d'ouvrir des créneaux, de bloquer une pause, ou de visualiser sa charge de la semaine en un coup d'œil.`}),(0,c.jsx)(s,{children:`Un fonctionnement adapté à la réalité du salon`}),(0,c.jsxs)(i,{children:[`Chaque salon a ses propres habitudes : durée des prestations, nombre de praticiens, politique d'annulation. Le module est configuré autour de votre organisation réelle, et intégré à votre propre site plutôt qu'à une plateforme tierce. Pour aller plus loin, découvrez l'ensemble de nos`,` `,(0,c.jsx)(n,{to:`/modules/`,className:`text-cyan-400 hover:text-cyan-300`,children:`modules métier`}),` `,`ou`,` `,(0,c.jsx)(n,{to:`/contact/`,className:`text-cyan-400 hover:text-cyan-300`,children:`contactez-nous`}),` `,`pour en discuter.`]})]})}export{u as default};